insert into public.cost_evidence_files(id,tenant_id,company_id,project_id,object_path,original_filename,declared_mime_type,declared_size_bytes,declared_sha256,verified_mime_type,verified_size_bytes,verified_sha256,status,intent_expires_at,created_by,finalized_by,finalized_at,version,workflow_origin,workflow_target_kind,workflow_evidence_kind)
select x.id,f.tenant_id,f.company_id,f.project_id,replace(f.object_path,f.id::text,x.id::text),x.filename,f.declared_mime_type,f.declared_size_bytes,x.hash,f.verified_mime_type,f.verified_size_bytes,x.hash,f.status,f.intent_expires_at,f.created_by,f.finalized_by,f.finalized_at,f.version,f.workflow_origin,f.workflow_target_kind,x.kind
from public.cost_evidence_files f cross join(values
 ('c1f50000-0000-4000-8000-000000000503'::uuid,'duplicate-invoice.pdf',repeat('a',64),'invoice'),
 ('c1f50000-0000-4000-8000-000000000504'::uuid,'duplicate-support.pdf',repeat('a',64),'accounting_support'),
 ('c1f50000-0000-4000-8000-000000000505'::uuid,'distinct-support.pdf',repeat('c',64),'accounting_support')
) x(id,filename,hash,kind) where f.id='c1f50000-0000-4000-8000-000000000501';

