select is((select n.delivery_state from public.cost_workflow_notifications n join public.cost_workflow_decisions d on d.id=n.decision_id join public.cost_workflow_request_versions v on v.id=d.submitted_version_id where v.request_id=(select value from workflow_test_ids where name='amendment')),'undelivered','inactive director retains same recipient event');
update public.projects set operational_state='completed' where id='c1f50000-0000-4000-8000-000000000101';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1f50000-0000-4000-8000-000000000901","role":"authenticated"}',true);
select throws_ok($$select public.c1_workflow_create_request('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101', ('{"partyId":"c1f50000-0000-4000-8000-000000000201","partyKind":"organization","categoryId":"c1f50000-0000-4000-8000-000000000211","amount":"70","currencyCode":"VND","basis":{"kind":"materials","lines":[{"description":"synthetic pipe","quantity":"1","unit":"item","unitPrice":"70"}],"deliverySite":"synthetic site"},"evidenceFileIds":["c1f50000-0000-4000-8000-000000000501"]}'::jsonb || jsonb_build_object('contractVersionId',(select body->>'contractVersionId' from workflow_test_ids where name='contract'))), 'c1f50000-0000-4000-8000-000000000729', 'c1f50000-0000-4000-8000-000000000730')$$,'P0001','PROJECT_COMPLETED','completed project rejects new obligation');
select is((select count(*) from public.cost_workflow_installments where tenant_id='c1f50000-0000-4000-8000-000000000010' and company_id='c1f50000-0000-4000-8000-000000000020' and project_id='c1f50000-0000-4000-8000-000000000101'),1::bigint,'amendment alone authorizes no extra installment');
select set_config('request.jwt.claims','{"sub":"c1f50000-0000-4000-8000-000000000903","role":"authenticated"}',true);
select throws_ok($$select public.c1_workflow_list_requests('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000102')$$,'P0001','PERMISSION_DENIED','unassigned project read must deny, never SQL null permission');
select * from finish();
rollback;
